def calculate_S_k(k, n_minus_1):
    S_k = 0
    for j in range(1, k + 1):
        S_k += (j**n_minus_1) * (math.factorial(j))
    return S_k

import math

# n=3, so n-1 = 2
n_minus_1 = 2
S = {}
for k in range(1, 6):
    S[k] = calculate_S_k(k, n_minus_1)

print("S_k values for n=3:")
print(S)

# Check consistency S_k == S_m mod gcd(k!, m!)
k_values = [1, 2, 3, 4, 5]
results = []
for k in k_values:
    for m in k_values:
        if k >= m:
            g = math.gcd(math.factorial(k), math.factorial(m))
            s_k = S[k]
            s_m = S[m]
            is_consistent = (s_k % g == s_m % g)
            results.append((k, m, g, s_k % g, s_m % g, is_consistent))

print("\nConsistency Checks (S_k mod gcd(k!, m!) == S_m mod gcd(k!, m!)):")
for k, m, g, rk, rm, consistent in results:
    if k >= m:
        print(f"k={k}, m={m}, gcd={g}: {rk} == {rm}? {consistent}")

